/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> fillSixGroupsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Sixteen sixteenths split as 6 + 6 + 4 do not sit on the beats; the accents land on 1, the \"a\" of 2 and the \"and\" of 3, then the four remaining notes bring you home. That drift is what makes a fill sound modern instead of square.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Time as written, then the fill with accents exactly where marked: first note of each group of six, and the first note of the final four. Keep everything else low and even. Listen for the accents against the band: they should feel like a slow triplet laid over the groove.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 1 is plain singles with the 6-6-4 accents, line 2 the paradiddle-diddle, line 3 the same groups turned around (4 + 6 + 6), line 5 R L L in groups of three. Clap the accents alone first, then add the hands.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Funk, fusion and gospel drumming, linear fills, the \"over the bar\" phrases of Dave Weckl and Jojo Mayer. Once you hear groups of six, you hear them everywhere.",
  ),
];
